 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import { Link } from 'react-router-dom'
import { 
  Calendar, 
  Filter, 
  Clock, 
  Trophy, 
  Home as HomeIcon,
  Plane,
  Minus,
  AlertCircle,
  Share2,
  CheckCircle,
  XCircle,
  Loader
} from 'lucide-react'
import { getTodaysMatches, formatMatch, COMPETITIONS } from '../services/footballApi'

export default function Matches() {
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const [matches, setMatches] = useState([])
    const [loading, setLoading] = useState(true)
    const [filter, setFilter] = useState('all')
    const [showModal, setShowModal] = useState(false)
    const [selectedMatch, setSelectedMatch] = useState(null)
    const [prediction, setPrediction] = useState({
        result: 'Draw',
        yellowCards: 2,
        redCards: 0,
        corners: 5,
        offsides: 1,
        isPublic: true,
        communityId: ''
    })
    const [submitting, setSubmitting] = useState(false)
    const [sharedPredictions, setSharedPredictions] = useState({})
    const [userCommunities, setUserCommunities] = useState([])
    const [selectedCommunityId, setSelectedCommunityId] = useState('')
    const [selectedCompetition, setSelectedCompetition] = useState(COMPETITIONS.PREMIER_LEAGUE)

    useEffect(() => {
        loadMatches()
        if (user) {
            loadUserSharedPredictions()
            loadUserCommunities()
        }
    }, [filter, selectedCompetition, user])

    const loadMatches = async () => {
        setLoading(true)
        try {
            const matchesData = await getTodaysMatches(selectedCompetition)
            const formattedMatches = matchesData.map(m => formatMatch(m))
            
            let filtered = formattedMatches
            if (filter === 'live') {
                filtered = formattedMatches.filter(m => m.status === 'live')
            } else if (filter === 'finished') {
                filtered = formattedMatches.filter(m => m.status === 'finished')
            } else if (filter === 'upcoming') {
                filtered = formattedMatches.filter(m => m.status === 'upcoming')
            }
            
            setMatches(filtered)
        } catch (error) {
            console.error('Error loading matches:', error)
            showToast('Failed to load matches', 'error')
        } finally {
            setLoading(false)
        }
    }

    const loadUserSharedPredictions = async () => {
        try {
            const { data: publicData } = await supabase
                .from('public_predictions')
                .select('match_id')
                .eq('user_id', user.id)
            
            const { data: communityData } = await supabase
                .from('community_posts')
                .select('match_id')
                .eq('user_id', user.id)

            const shared = {}
            publicData?.forEach(p => { shared[p.match_id] = true })
            communityData?.forEach(p => { shared[p.match_id] = true })
            setSharedPredictions(shared)
        } catch (error) {
            console.error('Error loading shared predictions:', error)
        }
    }

    const loadUserCommunities = async () => {
        if (!user) return
        
        try {
            const { data, error } = await supabase
                .from('communities')
                .select('id, name')
                .eq('creator_id', user.id)
            
            if (!error && data) {
                setUserCommunities(data)
                if (data.length > 0) {
                    setSelectedCommunityId(data[0].id)
                    setPrediction(prev => ({ ...prev, communityId: data[0].id }))
                }
            }
        } catch (error) {
            console.error('Error loading communities:', error)
        }
    }

    const openPredictionModal = (match) => {
        if (!user) {
            showToast('Please sign in to make predictions', 'warning')
            return
        }
        setSelectedMatch(match)
        setPrediction({
            result: 'Draw',
            yellowCards: 2,
            redCards: 0,
            corners: 5,
            offsides: 1,
            isPublic: true,
            communityId: userCommunities.length > 0 ? userCommunities[0].id : ''
        })
        setShowModal(true)
    }

    const closeModal = () => {
        setShowModal(false)
        setSelectedMatch(null)
    }

    const handleSubmitPrediction = async () => {
        if (!selectedMatch || !user) return
        
        setSubmitting(true)
        try {
            const { data: profileData } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .single()

            if (!profileData) {
                await supabase
                    .from('profiles')
                    .insert({
                        id: user.id,
                        username: user.email?.split('@')[0] || 'user',
                        full_name: user.email?.split('@')[0] || 'user'
                    })
            }

            if (prediction.isPublic) {
                const { error } = await supabase
                    .from('public_predictions')
                    .insert({
                        user_id: user.id,
                        match_id: selectedMatch.id || selectedMatch.matchId,
                        prediction_data: prediction
                    })
                
                if (error) throw error

                await supabase
                    .from('profiles')
                    .update({ 
                        points: (profile?.points || 0) + 10,
                        predictions_count: (profile?.predictions_count || 0) + 1
                    })
                    .eq('id', user.id)

                showToast('Prediction shared publicly! You earned 10 points!', 'success')

            } else {
                const communityId = prediction.communityId || selectedCommunityId

                if (!communityId) {
                    showToast('Please select a community first!', 'error')
                    setSubmitting(false)
                    return
                }

                const { data: communityData } = await supabase
                    .from('communities')
                    .select('id')
                    .eq('id', communityId)
                    .eq('creator_id', user.id)
                    .maybeSingle()

                if (!communityData) {
                    showToast('You can only share predictions to communities you created!', 'error')
                    setSubmitting(false)
                    return
                }

                const { error } = await supabase
                    .from('community_posts')
                    .insert({
                        community_id: communityId,
                        user_id: user.id,
                        match_id: selectedMatch.id || selectedMatch.matchId,
                        text: `My prediction for ${selectedMatch.homeTeam?.name || 'Home'} vs ${selectedMatch.awayTeam?.name || 'Away'}`,
                        prediction_data: prediction
                    })

                if (error) throw error

                const { data: commData } = await supabase
                    .from('communities')
                    .select('post_count')
                    .eq('id', communityId)
                    .single()

                await supabase
                    .from('communities')
                    .update({ 
                        post_count: (commData?.post_count || 0) + 1
                    })
                    .eq('id', communityId)

                showToast('Prediction shared in your community! Members can now see it.', 'success')
            }

            setSharedPredictions(prev => ({
                ...prev,
                [selectedMatch.id || selectedMatch.matchId]: true
            }))

            closeModal()
            await loadUserSharedPredictions()
            await loadMatches()

        } catch (error) {
            console.error('Error submitting prediction:', error)
            showToast('Failed to submit prediction: ' + error.message, 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const renderMatchCard = (match) => {
        const homeName = match.homeTeam?.name || 'Unknown'
        const awayName = match.awayTeam?.name || 'Unknown'
        const homeCrest = match.homeTeam?.crest
        const awayCrest = match.awayTeam?.crest
        const ai = match.aiPrediction || {}
        const isShared = sharedPredictions[match.id || match.matchId]
        
        let resultText = 'Draw'
        if (ai.result?.home > ai.result?.draw && ai.result?.home > ai.result?.away) resultText = 'Home Win'
        else if (ai.result?.away > ai.result?.home && ai.result?.away > ai.result?.draw) resultText = 'Away Win'

        const matchDate = match.kickoff ? new Date(match.kickoff) : new Date()
        const dateStr = matchDate.toLocaleDateString('en-US', { 
            weekday: 'short', 
            month: 'short', 
            day: 'numeric' 
        })
        const timeStr = matchDate.toLocaleTimeString('en-US', { 
            hour: '2-digit', 
            minute: '2-digit' 
        })

        const isLive = match.status === 'live'
        const isFinished = match.status === 'finished'

        return (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 hover:shadow-md transition">
                <div className="flex justify-between items-center mb-2">
                    <span className="text-xs text-gray-400">{match.league || 'Unknown League'}</span>
                    <div className="flex items-center gap-2">
                        {isShared && (
                            <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">Shared</span>
                        )}
                        {isLive && (
                            <span className="text-xs bg-red-100 text-red-600 px-2 py-0.5 rounded-full animate-pulse">● Live</span>
                        )}
                        {isFinished && (
                            <span className="text-xs bg-gray-100 text-gray-400 px-2 py-0.5 rounded-full">Finished</span>
                        )}
                    </div>
                </div>

                <div className="flex items-center justify-between py-3">
                    <div className="flex items-center gap-3">
                        {homeCrest ? (
                            <img src={homeCrest} alt={homeName} className="w-8 h-8 object-contain" />
                        ) : (
                            <span className="text-3xl">{match.homeTeam?.badge || '⚽'}</span>
                        )}
                        <span className="font-medium text-gray-800">{homeName}</span>
                    </div>
                    <div className="flex flex-col items-center">
                        <span className="text-gray-400 text-sm">vs</span>
                        {isLive || isFinished ? (
                            <span className="font-bold text-lg text-gray-800">
                                {match.score?.home || 0} - {match.score?.away || 0}
                            </span>
                        ) : null}
                    </div>
                    <div className="flex items-center gap-3">
                        <span className="font-medium text-gray-800">{awayName}</span>
                        {awayCrest ? (
                            <img src={awayCrest} alt={awayName} className="w-8 h-8 object-contain" />
                        ) : (
                            <span className="text-3xl">{match.awayTeam?.badge || '⚽'}</span>
                        )}
                    </div>
                </div>

                <div className="text-xs text-gray-400 text-center py-1 flex items-center justify-center gap-2">
                    <Calendar size={12} /> {dateStr} at {timeStr}
                </div>

                {ai.result && (
                    <div className="mt-3 bg-gray-50 rounded-lg p-3 border border-gray-100">
                        <div className="flex items-center justify-between">
                            <span className="text-xs text-gray-400">AI Prediction</span>
                            <span className="font-semibold text-gray-800">{resultText}</span>
                            <span className="text-xs text-gray-400">{ai.confidence || 0}%</span>
                        </div>
                        <div className="flex items-center justify-between text-xs text-gray-400 mt-1">
                            <span>🟨 {ai.yellowCards?.home + ai.yellowCards?.away || 0} cards</span>
                            <span>🟥 {ai.redCards?.home + ai.redCards?.away || 0} reds</span>
                            <span>🏁 {ai.corners?.home + ai.corners?.away || 0} corners</span>
                        </div>
                    </div>
                )}

                {!isFinished && (
                    <button 
                        onClick={() => openPredictionModal(match)}
                        disabled={isShared}
                        className={`w-full mt-3 py-2 rounded-lg font-medium transition flex items-center justify-center gap-1 ${
                            isShared 
                                ? 'bg-gray-100 text-gray-400 cursor-not-allowed' 
                                : 'bg-gray-800 text-white hover:bg-gray-900'
                        }`}
                    >
                        <Share2 size={16} /> {isShared ? 'Shared' : 'Predict'}
                    </button>
                )}
                {isFinished && (
                    <div className="w-full mt-3 py-2 text-center text-sm text-gray-400 bg-gray-50 rounded-lg flex items-center justify-center gap-1">
                        <XCircle size={16} /> Match finished
                    </div>
                )}
            </div>
        )
    }

    return (
        <div className="max-w-6xl mx-auto px-4 py-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        <Calendar size={24} /> Matches
                    </h1>
                    <p className="text-gray-400 text-sm">View matches and share your predictions</p>
                </div>
                
                <div className="flex gap-2 flex-wrap">
                    <select
                        value={selectedCompetition}
                        onChange={(e) => setSelectedCompetition(e.target.value)}
                        className="px-3 py-2 border border-gray-200 rounded-lg text-sm bg-white text-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-400"
                    >
                        <option value={COMPETITIONS.PREMIER_LEAGUE}>🏴 Premier League</option>
                        <option value={COMPETITIONS.LA_LIGA}>🇪🇸 La Liga</option>
                        <option value={COMPETITIONS.BUNDESLIGA}>🇩🇪 Bundesliga</option>
                        <option value={COMPETITIONS.SERIE_A}>🇮🇹 Serie A</option>
                        <option value={COMPETITIONS.LIGUE_1}>🇫🇷 Ligue 1</option>
                    </select>
                    
                    <button
                        onClick={() => setFilter('all')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'all' 
                                ? 'bg-gray-800 text-white' 
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setFilter('upcoming')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'upcoming' 
                                ? 'bg-gray-800 text-white' 
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                    >
                        Upcoming
                    </button>
                    <button
                        onClick={() => setFilter('live')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
                            filter === 'live' 
                                ? 'bg-red-600 text-white' 
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                    >
                        <Clock size={16} /> Live
                    </button>
                    <button
                        onClick={() => setFilter('finished')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'finished' 
                                ? 'bg-gray-800 text-white' 
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                        }`}
                    >
                        Finished
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <Loader className="w-8 h-8 text-gray-300 animate-spin mx-auto" />
                    <div className="text-gray-400 mt-2">Loading matches...</div>
                </div>
            ) : matches.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-sm border border-gray-100">
                    <Calendar className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400">No matches found</p>
                    <p className="text-sm text-gray-300">Try selecting a different league</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {matches.map(renderMatchCard)}
                </div>
            )}

            {!loading && matches.length > 0 && (
                <div className="text-center text-sm text-gray-400 mt-6">
                    Showing {matches.length} matches
                </div>
            )}

            {/* Prediction Modal */}
            {showModal && selectedMatch && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-xl max-w-md w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-6">
                            <div className="flex justify-between items-center mb-4">
                                <h2 className="text-xl font-bold text-gray-800">Share Prediction</h2>
                                <button 
                                    onClick={closeModal}
                                    className="text-gray-400 hover:text-gray-600 text-2xl"
                                >
                                    ×
                                </button>
                            </div>

                            <div className="bg-gray-50 rounded-lg p-3 mb-4 text-center border border-gray-100">
                                <div className="font-semibold text-gray-800">
                                    {selectedMatch.homeTeam?.name || 'Home'} vs {selectedMatch.awayTeam?.name || 'Away'}
                                </div>
                                <div className="text-sm text-gray-400">
                                    {selectedMatch.league || 'Unknown League'}
                                </div>
                            </div>

                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-2">Result</label>
                                    <div className="grid grid-cols-3 gap-2">
                                        {['Home Win', 'Draw', 'Away Win'].map((result) => (
                                            <button
                                                key={result}
                                                onClick={() => setPrediction({...prediction, result})}
                                                className={`px-3 py-2 rounded-lg text-sm font-medium transition flex items-center justify-center gap-1 ${
                                                    prediction.result === result
                                                        ? 'bg-gray-800 text-white'
                                                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                                }`}
                                            >
                                                {result === 'Home Win' ? <HomeIcon size={14} /> : 
                                                 result === 'Away Win' ? <Plane size={14} /> : <Minus size={14} />}
                                                {result === 'Home Win' ? 'Home' : 
                                                 result === 'Away Win' ? 'Away' : 'Draw'}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Yellow Cards</label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="10"
                                            value={prediction.yellowCards}
                                            onChange={(e) => setPrediction({...prediction, yellowCards: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Red Cards</label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="5"
                                            value={prediction.redCards}
                                            onChange={(e) => setPrediction({...prediction, redCards: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Corners</label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="20"
                                            value={prediction.corners}
                                            onChange={(e) => setPrediction({...prediction, corners: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 mb-1">Offsides</label>
                                        <input
                                            type="number"
                                            min="0"
                                            max="10"
                                            value={prediction.offsides}
                                            onChange={(e) => setPrediction({...prediction, offsides: parseInt(e.target.value) || 0})}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                        />
                                    </div>
                                </div>

                                <div className="bg-gray-50 rounded-lg p-3 border border-gray-100">
                                    <label className="flex items-center gap-3 cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={prediction.isPublic}
                                            onChange={(e) => setPrediction({...prediction, isPublic: e.target.checked})}
                                            className="w-5 h-5 accent-gray-800"
                                        />
                                        <div>
                                            <span className="font-medium text-gray-700">
                                                {prediction.isPublic ? 'Make this prediction public' : 'Keep private in community'}
                                            </span>
                                            <p className="text-sm text-gray-400">
                                                {prediction.isPublic 
                                                    ? 'Anyone can see this on the global Feed' 
                                                    : 'Only members of your community can see this'}
                                            </p>
                                        </div>
                                    </label>
                                </div>

                                {!prediction.isPublic && userCommunities.length > 0 && (
                                    <div className="bg-gray-50 rounded-lg p-3 border border-gray-100">
                                        <label className="block text-sm font-medium text-gray-700 mb-2">Choose Community</label>
                                        <select
                                            value={prediction.communityId}
                                            onChange={(e) => setPrediction({...prediction, communityId: e.target.value})}
                                            className="w-full px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                        >
                                            {userCommunities.map(community => (
                                                <option key={community.id} value={community.id}>
                                                    {community.name}
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                )}

                                {!prediction.isPublic && userCommunities.length === 0 && (
                                    <div className="bg-yellow-50 rounded-lg p-3 border border-yellow-200">
                                        <p className="text-sm text-yellow-700">
                                            You need to <Link to="/community/create" className="font-semibold underline">create a community</Link> first to share private predictions!
                                        </p>
                                    </div>
                                )}

                                <div className="bg-gray-50 rounded-lg p-3 text-center border border-gray-100">
                                    <p className="text-sm text-gray-400">
                                        Points you could earn: 
                                        <span className="font-bold text-gray-800 ml-1">
                                            {10 + (prediction.yellowCards * 2) + (prediction.corners * 1)}
                                        </span>
                                    </p>
                                </div>

                                <button
                                    onClick={handleSubmitPrediction}
                                    disabled={submitting || (!prediction.isPublic && !prediction.communityId && userCommunities.length > 0)}
                                    className="w-full bg-gray-800 text-white py-3 rounded-lg font-semibold hover:bg-gray-900 transition disabled:opacity-50 flex items-center justify-center gap-2"
                                >
                                    {submitting ? <Loader className="w-5 h-5 animate-spin" /> : <Share2 size={18} />}
                                    {submitting ? 'Sharing...' : 'Share Prediction'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
